import{_ as a,c as o,o as s,ah as i,ao as r,ap as t}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"Vou Ver Meu Pet de Novo? O Que a Bíblia Diz Sobre Animais e o Céu","description":"A pergunta mais profunda depois da perda de um pet: ele estará no céu? O que Romanos, Isaías e Apocalipse realmente oferecem.","frontmatter":{"title":"Vou Ver Meu Pet de Novo? O Que a Bíblia Diz Sobre Animais e o Céu","description":"A pergunta mais profunda depois da perda de um pet: ele estará no céu? O que Romanos, Isaías e Apocalipse realmente oferecem."},"headers":[],"relativePath":"pt/pets-in-heaven/will-i-see-my-pet-again.md","filePath":"pt/pets-in-heaven/will-i-see-my-pet-again.md"}'),n={name:"pt/pets-in-heaven/will-i-see-my-pet-again.md"};function p(u,e,l,d,m,c){return s(),o("div",null,[...e[0]||(e[0]=[i('<div class="pl-quote"><p>“Eu sei que estarei no céu. Só quero saber — ele estará lá me esperando?”</p><p class="pl-quote-soft">É a pergunta que quem perdeu um companheiro mais faz, e a que mais custa dizer em voz alta.</p></div><section class="pl-section"><h2>Uma palavra honesta primeiro</h2><p>A Bíblia nunca diz, em um único versículo, que “todo animal de estimação será reunido com seu dono no céu”. Quem afirma isso com tanta certeza foi além do que as Escrituras dizem.</p><p>Mas não se desespere por isso. O quadro que a Bíblia pinta é muito mais amplo do que supomos: a redenção de Deus nunca foi apenas “tirar algumas almas humanas dos escombros” — é <strong>a renovação de toda a criação</strong>. E os animais estão nesse quadro do início ao fim.</p></section><section class="pl-section"><h2>1. A própria criação espera conosco</h2><blockquote><p><strong>Romanos 8:19-22</strong></p><p>&quot;For the earnest expectation of the creature waiteth for the manifestation of the sons of God… For we know that the whole creation groaneth and travaileth in pain together until now.&quot;</p></blockquote><p>Paulo diz algo surpreendente aqui: não são apenas as pessoas que gemem e esperam. <em>A própria criação</em> geme e espera a redenção. Os animais não são cenário deixado fora da salvação — eles olham para o mesmo desfecho que nós.</p><p>Quando você diz “ele era tão bom — não deveria simplesmente ter desaparecido”, o que você sente é exatamente o que a criação sente. A Escritura diz que essa dor será respondida.</p></section><section class="pl-section"><h2>2. O mundo que Deus vai fazer tem animais</h2><blockquote><p><strong>Isaías 11:6-9</strong></p><p>&quot;The wolf also shall dwell with the lamb, and the leopard shall lie down with the kid; and the calf and the young lion and the fatling together; and a little child shall lead them.&quot;</p></blockquote><p>O futuro que Isaías viu não é um mundo só de luz e nuvens. Ele viu lobos, cordeiros, leopardos, cabritos, bezerros e leões — um mundo onde nada fere e todos se deitam em segurança.</p><p>Se a intenção de Deus para os animais fosse “eles são só para esta vida e depois acabou”, Ele não lhes teria dado lugar nas Suas promessas. Ele deu.</p><p>E ao descrever o novo céu e a nova terra, o Apocalipse diz:</p><blockquote><p><strong>Apocalipse 21:4-5</strong></p><p>&quot;And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away. …Behold, I make all things new.&quot;</p></blockquote><p>“Não haverá mais morte” é um anúncio feito sobre toda a criação. A morte que o seu pet atravessou é uma das coisas que será abolida.</p></section><section class="pl-section"><h2>3. Até onde podemos ter esperança?</h2><p>Podemos ter esperança, porque Deus não abandona o que criou. Podemos ter esperança, porque a ressurreição de Cristo é as primícias de uma nova criação, e a Escritura diz que o alcance dessa nova criação é “todas as coisas”. Podemos ter esperança, porque o Deus que criou os animais e se agradou deles não vai de repente parar de se importar com eles.</p><p>Quanto a “será o mesmo?” e “ele vai se lembrar de mim?” — a Bíblia não dá detalhes. Ela nos dá um Deus digno de confiança, e os detalhes estão nas mãos Dele. Esse silêncio não é para nos torturar; é um convite a entregar o que não sabemos a mãos boas.</p><p class="pl-quote-soft">Se quiser, você pode orar assim:</p></section><div class="pl-quote"><p>“Senhor, eu não sei os detalhes do céu, mas creio que Tu és bom.<br>Tu o criaste. Tu cuidaste de cada dia da vida dele. Tu vês minhas lágrimas agora.<br>Eu o coloco em Tuas mãos — como coloco a mim mesmo em Tuas mãos.<br>Se há um lugar para ele em Tuas promessas, obrigado.<br>E se alguém precisa cuidar dele agora, fico feliz que seja Tu. Amém.”</p></div><section class="pl-section"><h2>Para um dia especialmente difícil</h2><p>O salmista escreveu: “ó Senhor, tu preservas o homem e o animal” (Salmos 36:6). É uma linha curta, mas é um dos raros versículos que colocam os animais diretamente dentro do cuidado preservador de Deus.</p><p>Seu pet pertence ao Deus que preserva “o homem e o animal”. O que você talvez precise hoje não é uma resposta completa — é apenas isto: ele está nas mãos de Deus, e Deus é bom.</p><p><a href="/pt/pets-in-heaven/">← Voltar para Pets in Heaven</a> ｜ Próximo: <a href="/pt/pets-in-heaven/not-one-sparrow-forgotten">Nem um Pardal É Esquecido</a></p></section><div class="pl-cta"><h2>Escreva o nome dele.</h2><p>Escreva o nome dele, o lugar favorito, a frase que você nunca disse. O PetLoss é um espaço privado — sem uploads, sem pressa — que ajuda você a organizar isso devagar.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Baixar na App Store</a></div><div class="pl-bible"><h3>Deixe a Palavra de Deus continuar com você</h3><p>Todos os versículos deste artigo vêm da Bíblia. Com o Rainbow Bible, você pode ler as Escrituras a qualquer momento e criar um widget de versículo diário — uma pequena luz nos dias em que sente saudade.</p><div class="pl-bible-shots"><figure><img src="'+r+'" alt="Widget do Rainbow Bible exibindo 2 Timóteo 2:13" loading="lazy"><figcaption>Versículo diário na tela inicial</figcaption></figure><figure><img src="'+t+'" alt="App Rainbow Bible — tema Pets no Céu exibindo Mateus 10:29-31" loading="lazy"><figcaption>Leia a Palavra no tema Pets no Céu</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Baixar o Rainbow Bible na App Store</a></div>',9)])])}const g=a(n,[["render",p]]);export{v as __pageData,g as default};
